                const removeItemBtn = document.querySelector('.remove-item-btn');
                const arrayFieldInput = document.querySelector('input[name="{name}"]');
                let currentCount = 0;

                addItemBtn.addEventListener('click', () => {
                    const newInput = document.createElement('input');
                    newInput.type = 'text';
                    newInput.name = '{name}[{currentCount}]';
                    newInput.placeholder = `Item ${currentCount + 1}`;
                    newInput.value = '';
                    newInput.onkeydown = (e) => {
                        if (e.key === 'Enter') {
