                        }
                    };
                    newInput.onblur = () => {
                        if (newInput.value.trim() === '') {
                            newInput.remove();
                        }
                    };
                    arrayFieldInput.parentNode.insertBefore(newInput, addItemBtn);
                    currentCount++;
                });

                removeItemBtn.addEventListener('click', () => {
                    const items = arrayFieldInput.parentNode.children;
                    if (items.length > 1) {
                        arrayFieldInput.parentNode.removeChild(items[items.length - 1]);
                        currentCount--;
                    }
                });
            </script>
            <style>
               .array-field-container {
                    display: flex;
                    flex-direction: column;
                }
               .array-field-container input[type="text"] {
                    margin-bottom: 10px;
                }
               .array-field-container button[type="button"] {
                    margin-left: 10px;
                }
            </style>
        """
        return mark_safe(html)

class ArrayField(forms.CharField):
    widget = ArrayFieldWidget

    def to_python(self, value):
        if not value:
            return []
        return [item.strip() for item in value.split(',')]
