        self.version_dir = version_dir
        self.git_dir = git_dir
        self.repos = {}

    def create_repo(self, version):
        repo_path = os.path.join(self.version_dir, version)
        if not os.path.exists(repo_path):
            os.makedirs(repo_path)
        self.repos[version] = git.Repo.init(repo_path)

    def add_file(self, version, file_path, content):
        repo = self.repos[version]
        repo.git.add(file_path)
        repo.git.commit('-m', f'Added file {file_path}')

    def switch_version(self, version):
        try:
            shutil.rmtree(self.version_dir)
        except FileNotFoundError:
            pass
        shutil.copytree(os.path.join(self.git_dir, f'v{version}'), self.version_dir)
        os.chdir(self.version_dir)

    def track_changes(self):
        for version in self.repos:
            repo = self.repos[version]
            print(f'Changes in version {version}:')
            for commit in repo.iter_commits():
                print(commit.summary)

