from text_maze import create_maze
import random

def generate_maze():
    width, height = 21, 11
    maze = create_maze(width, height)
    start = (0, 0)
    end = (width - 1, height - 1)

    # Randomly block some paths
    for _ in range(width * height // 2):
        x, y = random.randint(0, width - 1), random.randint(0, height - 1)
        maze[y][x] = 'X'

    return start, end, maze

def print_maze(maze):
    for row in maze:
        print(' '.join(row))

def main():
    start, end, maze = generate_maze()
    print("Welcome to the text-based maze game!")
    print("Your goal is to find the exit.")
    print_maze(maze)

    while True:
        direction = input("Enter a direction (N/S/E/W): ")
        if direction.upper() == 'N':
            x, y = start[0], start[1] - 1
        elif direction.upper() == 'S':
            x, y = start[0], start[1] + 1
        elif direction.upper() == 'E':
            x, y = start[0] + 1, start[1]
        elif direction.upper() == 'W':
            x, y = start[0] - 1, start[1]
        else:
            print("Invalid direction. Please try again.")
            continue

        if x < 0 or y < 0 or x >= len(maze[0]) or y >= len(maze):
            print("You cannot move that way. Please try again.")
            continue

        if maze[y][x] == 'X':
            print("You hit a wall. Please try again.")
            continue

        if (x, y) == end:
            print(" Congratulations, you found the exit!")
            break

        start = (x, y)
        print_maze(maze)

