        ('data_create', 'Data Create'),
        ('data_update', 'Data Update'),
        ('data_delete', 'Data Delete'),
    )

    event_type = models.CharField(max_length=255, choices=EVENT_TYPES)
    event_date = models.DateTimeField(auto_now_add=True)
    user = models.ForeignKey(User, on_delete=models.CASCADE)
    details = models.TextField(blank=True)

    def __str__(self):
        return f"{self.event_type} by {self.user.username} on {self.event_date}"

class LogFilter(models.Model):
    log = models.OneToOneField(Log, on_delete=models.CASCADE)
    filtered = models.BooleanField(default=False)

    def __str__(self):
        return f"LogFilter for {self.log}"

# views.py
from django.shortcuts import render
from django.contrib.auth.decorators import login_required
from django.db.models import Q
from.models import Log

@login_required
def log_list(request):
    logs = Log.objects.all()
    return render(request, 'log_list.html', {'logs': logs})

@login_required
def log_dashboard(request):
    if request.method == 'POST':
        event_type = request.POST.get('event_type')
        start_date = request.POST.get('start_date')
        end_date = request.POST.get('end_date')
        user = request.POST.get('user')
        logs = Log.objects.filter(
            Q(event_type__startswith=event_type) &
            Q(event_date__range=(start_date, end_date)) &
            Q(user__username=user)
        )
    else:
        logs = Log.objects.all()
    return render(request, 'log_dashboard.html', {'logs': logs})

