import dash_html_components as html
from dash.dependencies import Input, Output
import dash_mantine_components as dmc
import pandas as pd

# Initialize the app
app = dash.Dash(__name__)

# Create a sample dataframe
df = pd.DataFrame({
    'Country': ['USA', 'Canada', 'Germany', 'UK', 'Australia'],
    'Population': [331002651, 37742154, 83719900, 67261900, 25851496]
})

# Create the layout
app.layout = dmc.Container(
    style={'width': '100%', 'padding': '20px'},
    children=[
        dmc.Group(
            direction='column',
            grow=True,
            p='xl',
            children=[
                dmc.Text('Data Insights Dashboard', variant='heading', size='xl'),
                dmc.Space(h=20),
                html.H2('Select a Country'),
                dcc.Dropdown(
                    id='country-dropdown',
                    options=[{'label': country, 'value': country} for country in df['Country'].unique()],
                    value=df['Country'].unique()[0]
                ),
                dmc.Space(h=20),
                html.H2('Data Insights'),
                dcc.Graph(id='data-insights-graph')
            ]
        )
    ]
)

# Update the graph based on the selected country
@app.callback(
    Output('data-insights-graph', 'figure'),
    [Input('country-dropdown', 'value')]
)
def update_graph(selected_country):
    filtered_df = df[df['Country'] == selected_country]
    fig = {
        'data': [
            {'x': filtered_df['Country'], 'y': filtered_df['Population'], 'type': 'bar'}
        ],
        'layout': {
            'title': f'{selected_country} Population',
            'xaxis': {'title': 'Country'},
            'yaxis': {'title': 'Population'}
        }
    }
    return fig

# Run the app
if __name__ == '__main__':
    app.run_server(debug=True)

